  C_RESET=$'\033[0m'
  C_BOLD=$'\033[1m'
  C_DIM=$'\033[2m'
  C_CYAN=$'\033[36m'
  C_GREEN=$'\033[32m'
  C_YELLOW=$'\033[33m'
  C_BLUE=$'\033[34m'
  C_RED=$'\033[31m'
  C_WHITE=$'\033[97m'
else
  C_RESET=""
  C_BOLD=""
  C_DIM=""
  C_CYAN=""
  C_GREEN=""
  C_YELLOW=""
  C_BLUE=""
  C_RED=""
  C_WHITE=""
fi

USER_HOME="${USERPROFILE:-${HOME}}"
if command -v cygpath >/dev/null 2>&1; then
  USER_HOME="$(cygpath -u "${USER_HOME}" 2>/dev/null || echo "${USER_HOME}")"
elif command -v wslpath >/dev/null 2>&1 && [[ "${USER_HOME}" == *":"* ]]; then
  USER_HOME="$(wslpath -u "${USER_HOME}" 2>/dev/null || echo "${HOME}")"
fi
if [[ ! -d "${USER_HOME}" ]]; then
  mkdir -p "${USER_HOME}" 2>/dev/null || USER_HOME="${HOME}"
fi
USER_HOME="$(cd "${USER_HOME}" && pwd)"
WIN_HOME="${USER_HOME}"
if command -v cygpath >/dev/null 2>&1; then
  WIN_HOME="$(cygpath -w "${USER_HOME}" 2>/dev/null || echo "${USER_HOME}")"
fi

HOST_NAME="${COMPUTERNAME:-$(hostname 2>/dev/null || echo "Workstation")}"
USER_NAME="${USERNAME:-${USER:-developer}}"
OS_INFO="$(uname -s) $(uname -m)"

# Gerar Identificador (QID) deterministico da estacao
SEED_STR="SQUAD-V10113|${HOST_NAME}|${USER_NAME}|${OS_INFO}"
if command -v sha256sum >/dev/null 2>&1; then
  RAW_HASH="$(printf "%s" "${SEED_STR}" | sha256sum | awk '{print toupper($1)}')"
elif command -v shasum >/dev/null 2>&1; then
  RAW_HASH="$(printf "%s" "${SEED_STR}" | shasum -a 256 | awk '{print toupper($1)}')"
else
  RAW_HASH="8F4A9C2E7B1D6053A4E8F2C19B7D3E6A"
fi
QID="QUID-SQ8-${RAW_HASH:0:4}-${RAW_HASH:4:4}-${RAW_HASH:8:4}-${RAW_HASH:12:4}"

SQUAD_USER_DIR="${USER_HOME}/.squad-ai"
GEN_FILE="${SQUAD_USER_DIR}/install-generation.txt"
