SQUAD_TEAM="${SQUAD_TEAM:-${DEFAULT_SQUAD_TEAM}}"
if [[ -f "${SQUAD_USER_DIR}/station-team.txt" ]]; then
  SAVED_TEAM="$(head -n 1 "${SQUAD_USER_DIR}/station-team.txt" 2>/dev/null | tr -d ' \t\r\n' || true)"
  [[ -n "${SAVED_TEAM}" ]] && SQUAD_TEAM="${SAVED_TEAM}"
fi

