get_current_gen() {
  if [[ -f "${GEN_FILE}" ]]; then
    cat "${GEN_FILE}" | tr -d '\r\n ' || echo "1"
  elif [[ -f "${SQUAD_USER_DIR}/station-profile.json" ]]; then
    echo "1"
  else
    echo "0"
  fi
}

print_step() {
  local step_num="$1"
  local total_steps="$2"
  local step_desc="$3"
  local pct=$(( step_num * 100 / total_steps ))
  local filled=$(( step_num * 20 / total_steps ))
  local empty=$(( 20 - filled ))
  local bar=""
  local i
  for ((i=0; i<filled; i++)); do bar="${bar}#"; done
  for ((i=0; i<empty; i++)); do bar="${bar}-"; done
  printf "${C_CYAN}[%02d/%02d]${C_RESET} ${C_GREEN}[%s]${C_RESET} ${C_BOLD}%3d%%${C_RESET}  %s\n" \
    "${step_num}" "${total_steps}" "${bar}" "${pct}" "${step_desc}"
}

